	"example.com/tally/internal/store"
)

// Temporary golden capture: records every answer of GET /v1/invoices for a fixed fixture.
func TestZZGoldenCapture(t *testing.T) {
	dir := os.Getenv("GOLDEN_OUT")
	if dir == "" {
		t.Skip("GOLDEN_OUT not set")
	}
	os.MkdirAll(dir, 0o755)
	n := 0
	rec := func(name string, body []byte, code int) {
		n++
		f := filepath.Join(dir, fmt.Sprintf("%04d-%s.txt", n, name))
		os.WriteFile(f, []byte(fmt.Sprintf("%d\n%s", code, body)), 0o644)
	}
	e := apitest.New(t)
	var cus []store.Customer
	for i := 0; i < 4; i++ {
		cus = append(cus, e.CreateCustomer(e.Acme, fmt.Sprintf("Cust %d", i), fmt.Sprintf("c%d@acme.example", i)))
	}
	gc := e.CreateCustomer(e.Globex, "Globex one", "g1@globex.example")
	subs := []string{"sub_a", "sub_b", ""}
	now := apitest.Start
	for i := 0; i < 300; i++ {
		switch {
		case i%7 == 3:
			now = now.Add(-time.Hour) // clock skew: created earlier than the previous invoice
		case i%5 == 0:
			// same timestamp as the previous invoice: ties broken by ID
		default:
			now = now.Add(time.Minute)
		}
		e.Clock.Set(now)
		lines := []store.Line{{Description: fmt.Sprintf("Item %d", i), Quantity: 1 + i%3, UnitAmount: int64(100 + i)}}
		if i%4 == 0 {
			lines = append(lines, store.Line{Description: "extra", Quantity: 2, UnitAmount: 333})
		}
		cur := money.USD
		if i%6 == 0 {
			cur = money.EUR
		}
		_, err := e.Store.CreateInvoice(store.Invoice{OrgID: e.Acme.ID, CustomerID: cus[i%4].ID, SubscriptionID: subs[i%3], Currency: cur, Lines: lines, DiscountPercent: (i % 3) * 5}, now)
		if err != nil {
			t.Fatal(err)
		}
	}
	for i := 0; i < 60; i++ {
		now = now.Add(time.Minute)
		e.Clock.Set(now)
		if _, err := e.Store.CreateInvoice(store.Invoice{OrgID: e.Globex.ID, CustomerID: gc.ID, Currency: money.USD, Lines: []store.Line{{Description: "G", Quantity: 1, UnitAmount: 5}}}, now); err != nil {
			t.Fatal(err)
		}
	}
	// Some statuses change through the API, the way production does.
	all := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{})
	for i, inv := range all {
		if i%11 == 5 {
			e.Do("POST", "/v1/invoices/"+inv.ID+"/void", e.Acme.Key, nil)
		} else if i%13 == 7 {
			e.Do("POST", "/v1/invoices/"+inv.ID+"/pay", e.Acme.Key, map[string]string{"payment_method": "pm_card_visa"})
		}
	}
	// A customer deleted after invoicing: its invoices now show "customer": null.
	e.Do("DELETE", "/v1/customers/"+cus[2].ID, e.Acme.Key, nil)

	filters := []string{"", "customer_id=" + cus[0].ID, "customer_id=" + cus[2].ID, "customer_id=cus_nope", "subscription_id=sub_a", "subscription_id=sub_b",
		"subscription_id=sub_none", "status=open", "status=paid", "status=void", "status=", "customer_id=" + cus[1].ID + "&status=open",
		"subscription_id=sub_a&status=paid", "customer_id=" + gc.ID, "customer_id=" + cus[0].ID + "&subscription_id=sub_b&status=void"}
	for fi, f := range filters {
		for _, lim := range []int{0, 1, 3, 7, 20, 100, 101} {
			q := "/v1/invoices?" + f
			if lim != 0 {
				q += fmt.Sprintf("&limit=%d", lim)
			}
			r := e.Do("GET", q, e.Acme.Key, nil)
			rec(fmt.Sprintf("f%02d-l%d-first", fi, lim), r.Body, r.Code)
		}
		// Full paging at limit 3 and 7 and 100.
		for _, lim := range []int{1, 3, 7, 100} {
			cursor := ""
			for p := 0; p < 500; p++ {
				q := fmt.Sprintf("/v1/invoices?%s&limit=%d", f, lim)
				if cursor != "" {
					q += "&cursor=" + cursor
				}
				r := e.Do("GET", q, e.Acme.Key, nil)
				rec(fmt.Sprintf("f%02d-l%d-p%03d", fi, lim, p), r.Body, r.Code)
				m := r.Map(t)
				next, _ := m["next_cursor"].(string)
				if next == "" {
					break
				}
				cursor = next
			}
		}
	}
	// Invalid requests.
	for _, q := range []string{"?limit=0", "?limit=101", "?limit=abc", "?cursor=!!!", "?cursor=e30", "?status=lost", "?status=OPEN"} {
		r := e.Do("GET", "/v1/invoices"+q, e.Acme.Key, nil)
		rec("invalid"+q, r.Body, r.Code)
	}
	// Another organization's key sees only its own invoices.
	r := e.Do("GET", "/v1/invoices?limit=100", e.Globex.Key, nil)
	rec("globex-first", r.Body, r.Code)
	r = e.Do("GET", "/v1/invoices?customer_id="+cus[0].ID, e.Globex.Key, nil)
