package store

import (
	"reflect"
	"sort"
	"testing"
	"time"

	"example.com/tally/internal/money"
)

// referenceInvoices is the list ListInvoices must answer, worked out from the whole store rather than the index.
func referenceInvoices(s *Store, orgID string, f InvoiceFilter) []Invoice {
	out := []Invoice{}
	for _, inv := range s.Export().Invoices {
		if inv.OrgID != orgID {
			continue
		}
		if (f.CustomerID != "" && inv.CustomerID != f.CustomerID) || (f.SubscriptionID != "" && inv.SubscriptionID != f.SubscriptionID) || (f.Status != "" && inv.Status != f.Status) {
			continue
		}
		out = append(out, inv)
	}
	sort.Slice(out, func(i, j int) bool {
		if !out[i].CreatedAt.Equal(out[j].CreatedAt) {
			return out[i].CreatedAt.Before(out[j].CreatedAt)
		}
		return out[i].ID < out[j].ID
	})
	return out
}

func invoiceIDs(invs []Invoice) []string {
	ids := []string{}
	for _, inv := range invs {
		ids = append(ids, inv.ID)
	}
	return ids
}

// fillInvoices creates invoices for two organizations: several share a timestamp, some are created with the clock turned
// back, some are paid, and some carry a subscription.
func fillInvoices(t *testing.T, s *Store, n int) (a, b Org, ca, cb Customer) {
	t.Helper()
	a, b = newOrg(t, s, "A"), newOrg(t, s, "B")
	ca, _ = s.CreateCustomer(a.ID, "Ann", "ann@a.example", t0)
	cb, _ = s.CreateCustomer(b.ID, "Bob", "bob@b.example", t0)
	subs := []string{"", "sub_1", "sub_2"}
	for i := 0; i < n; i++ {
		org, cus := a, ca
		if i%4 == 3 {
			org, cus = b, cb
		}
		now := t0.Add(time.Duration(i/3) * time.Minute)
		if i%17 == 16 {
			now = t0.Add(-time.Duration(i) * time.Second) // the clock went back
		}
		inv, err := s.CreateInvoice(Invoice{OrgID: org.ID, CustomerID: cus.ID, SubscriptionID: subs[i%3], Currency: money.USD,
			Lines: []Line{{Description: "x", Quantity: 1, UnitAmount: int64(i)}}}, now)
		if err != nil {
			t.Fatal(err)
		}
		if i%5 == 0 {
			if _, err := s.UpdateInvoice(org.ID, inv.ID, func(i *Invoice) error { i.Status = InvoicePaid; return nil }); err != nil {
				t.Fatal(err)
			}
		}
	}
	return a, b, ca, cb
}

var testFilters = func(ca, cb Customer) []InvoiceFilter {
	return []InvoiceFilter{
		{}, {CustomerID: ca.ID}, {CustomerID: cb.ID}, {CustomerID: "cus_none"}, {SubscriptionID: "sub_1"},
		{SubscriptionID: "sub_2", Status: InvoiceOpen}, {Status: InvoicePaid}, {Status: InvoiceOpen}, {Status: InvoiceVoid},
		{CustomerID: ca.ID, Status: InvoiceOpen},
	}
}

func TestInvoicePageMatchesTheListOrder(t *testing.T) {
	s := New()
	a, b, ca, cb := fillInvoices(t, s, 120)
	for _, org := range []Org{a, b} {
		for _, f := range testFilters(ca, cb) {
			want := referenceInvoices(s, org.ID, f)
			if got := s.ListInvoices(org.ID, f); !reflect.DeepEqual(invoiceIDs(got), invoiceIDs(want)) {
				t.Fatalf("ListInvoices(%+v) = %v, want %v", f, invoiceIDs(got), invoiceIDs(want))
			}
			for limit := 1; limit <= 9; limit++ {
				var got []Invoice
				var after *InvoicePosition
				for pages := 0; ; pages++ {
					if pages > len(want) {
						t.Fatalf("paging %+v at %d never ends", f, limit)
					}
					page, more := s.InvoicePage(org.ID, f, after, limit)
					if len(page) > limit || (more && len(page) != limit) {
						t.Fatalf("page of %d with limit %d, more=%v", len(page), limit, more)
					}
					got = append(got, page...)
					if !more {
						break
					}
					last := page[len(page)-1]
					after = &InvoicePosition{At: last.CreatedAt, ID: last.ID}
				}
				if !reflect.DeepEqual(invoiceIDs(got), invoiceIDs(want)) {
					t.Fatalf("paging %+v with limit %d = %v, want %v", f, limit, invoiceIDs(got), invoiceIDs(want))
				}
			}
			// A page that starts after each invoice of the list is the rest of the list.
			for k, inv := range want {
				page, more := s.InvoicePage(org.ID, f, &InvoicePosition{At: inv.CreatedAt, ID: inv.ID}, 1000)
				if !reflect.DeepEqual(invoiceIDs(page), invoiceIDs(want[k+1:])) || more {
					t.Fatalf("after %s: %v, want %v", inv.ID, invoiceIDs(page), invoiceIDs(want[k+1:]))
				}
			}
		}
	}
	if got, more := s.InvoicePage(a.ID, InvoiceFilter{}, nil, 0); len(got) != 0 || !more {
		t.Fatalf("limit 0 = %v, more %v", got, more)
	}
	if got, _ := s.InvoicePage("org_none", InvoiceFilter{}, nil, 10); got == nil || len(got) != 0 {
		t.Fatalf("an organization without invoices = %v, want an empty list", got)
	}
}

func TestInvoicePageAfterAPositionThatIsNotAnInvoice(t *testing.T) {
	s := New()
	a, _, ca, cb := fillInvoices(t, s, 30)
	at := t0.Add(4 * time.Minute)
	for _, f := range testFilters(ca, cb) {
		var want []Invoice
		for _, inv := range referenceInvoices(s, a.ID, f) {
			if !inv.CreatedAt.Before(at) {
				want = append(want, inv)
			}
		}
		got, _ := s.InvoicePage(a.ID, f, &InvoicePosition{At: at}, 1000)
		if !reflect.DeepEqual(invoiceIDs(got), invoiceIDs(want)) {
			t.Fatalf("after %s with %+v: %v, want %v", at, f, invoiceIDs(got), invoiceIDs(want))
		}
	}
}

func TestInvoicesCreatedBetweenPagesKeepTheCursorWorking(t *testing.T) {
	s := New()
	a, _, ca, _ := fillInvoices(t, s, 40)
	page, more := s.InvoicePage(a.ID, InvoiceFilter{}, nil, 10)
	if !more {
		t.Fatal("expected more invoices")
	}
	last := page[len(page)-1]
	pos := &InvoicePosition{At: last.CreatedAt, ID: last.ID}

	// A newer invoice comes after the cursor; an older one (the clock went back) is before it and is not listed again.
	newer, _ := s.CreateInvoice(Invoice{OrgID: a.ID, CustomerID: ca.ID, Currency: money.USD, Lines: []Line{{Description: "n", Quantity: 1, UnitAmount: 1}}}, t0.Add(time.Hour))
	older, _ := s.CreateInvoice(Invoice{OrgID: a.ID, CustomerID: ca.ID, Currency: money.USD, Lines: []Line{{Description: "o", Quantity: 1, UnitAmount: 1}}}, t0.Add(-time.Hour))

	var got []string
	for {
		page, more := s.InvoicePage(a.ID, InvoiceFilter{}, pos, 7)
		got = append(got, invoiceIDs(page)...)
		if !more {
			break
		}
		last := page[len(page)-1]
		pos = &InvoicePosition{At: last.CreatedAt, ID: last.ID}
	}
	want := []string{}
	for _, inv := range referenceInvoices(s, a.ID, InvoiceFilter{}) {
		if inv.CreatedAt.After(last.CreatedAt) || (inv.CreatedAt.Equal(last.CreatedAt) && inv.ID > last.ID) {
			want = append(want, inv.ID)
		}
	}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("rest of the list = %v, want %v", got, want)
	}
	if got[len(got)-1] != newer.ID {
		t.Fatalf("the newer invoice %s is not last in %v", newer.ID, got)
	}
	for _, id := range got {
		if id == older.ID {
			t.Fatalf("the older invoice %s was listed after the cursor", older.ID)
		}
	}
}

func TestInvoiceOrderSurvivesSnapshot(t *testing.T) {
	s := New()
	a, _, ca, cb := fillInvoices(t, s, 60)
	restored, err := FromState(s.Export())
	if err != nil {
		t.Fatal(err)
	}
	for _, f := range testFilters(ca, cb) {
		if got, want := invoiceIDs(restored.ListInvoices(a.ID, f)), invoiceIDs(s.ListInvoices(a.ID, f)); !reflect.DeepEqual(got, want) {
			t.Fatalf("restored %+v = %v, want %v", f, got, want)
		}
	}
	// New invoices after a restore go in the right place too, including one from before the others.
	early, _ := restored.CreateInvoice(Invoice{OrgID: a.ID, CustomerID: ca.ID, Currency: money.USD, Lines: []Line{{Description: "e", Quantity: 1, UnitAmount: 1}}}, t0.Add(-time.Hour))
	if got := restored.ListInvoices(a.ID, InvoiceFilter{}); got[0].ID != early.ID || !reflect.DeepEqual(invoiceIDs(got), invoiceIDs(referenceInvoices(restored, a.ID, InvoiceFilter{}))) {
		t.Fatalf("after restore, the list starts with %s: %v", got[0].ID, invoiceIDs(got))
	}
}

func BenchmarkInvoicePageOfLargeOrganization(b *testing.B) {
	s := New()
	a, _, ca, _ := fillInvoices(&testing.T{}, s, 60000)
	pos := &InvoicePosition{At: t0.Add(5000 * time.Minute)}
	for i := 0; i < b.N; i++ {
		s.InvoicePage(a.ID, InvoiceFilter{CustomerID: ca.ID}, pos, 20)
	}
}

func BenchmarkCreateInvoice(b *testing.B) {
	s := New()
	o := newOrg(&testing.T{}, s, "A")
	c, _ := s.CreateCustomer(o.ID, "Ann", "ann@a.example", t0)
	inv := Invoice{OrgID: o.ID, CustomerID: c.ID, Currency: money.USD, Lines: []Line{{Description: "x", Quantity: 1, UnitAmount: 1}}}
	for i := 0; i < b.N; i++ {
		if _, err := s.CreateInvoice(inv, t0.Add(time.Duration(i)*time.Second)); err != nil {
			b.Fatal(err)
		}
	}
}

